    when(resourceProviderMock.createResources(requestMock)).thenAnswer(invocation -> requestStatusMock);
    when(requestStatusMock.getRequestResource()).thenAnswer(invocation -> responseResourceMock);
    when(responseResourceMock.getPropertyValue(anyString())).thenAnswer(invocation -> 100l);
