                namenodeFailedEvent = event;
            }
        }
    }
    Assert.assertNotNull("Datanode should be in Install failed state.", datanodeFailedEvent);
    Assert.assertNotNull("Namenode should be in Install failed state.", namenodeFailedEvent);
}

