    //Now change the action status
    s.setHostRoleStatus(hostname, "NAMENODE", HostRoleStatus.COMPLETED);
    //Wait for sometime, it shouldn't be scheduled this time.
    scheduler.doWork();
    EasyMock.verify(entityManagerProviderMock);
}

